/**
 * Drizzle ORM schema (Part 1 foundation).
 *
 * Defines the core persistence model for the always-on backend:
 *  - `api_clients`   — registered APK installs/devices (auth boundary subject).
 *  - `products`      — normalized products imported from the Shopee feed.
 *  - `jobs`          — durable scheduler job queue (uniqueness + retry).
 *  - `publish_runs`  — per-slot record of what was published where.
 *  - `notifications` — outbound Telegram notification ledger (dedupe).
 *
 * All timestamps are stored as timestamptz. Ids are UUIDs generated by the
 * application (not DB-side) so the same code path works on SQLite during tests.
 */
import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';

/* -------------------------------------------------------------------------- */
/*  API clients (APK installs)                                                */
/* -------------------------------------------------------------------------- */

export const apiClients = pgTable(
  'api_clients',
  {
    id: uuid('id').primaryKey(),
    /** Human label for the install (device model, user note). */
    label: varchar('label', { length: 255 }),
    /** Granted scopes, space-delimited. */
    scopes: text('scopes').notNull().default('dashboard read'),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }),
  },
  (t) => [uniqueIndex('api_clients_label_idx').on(t.label)],
);

/* -------------------------------------------------------------------------- */
/*  Products                                                                   */
/* -------------------------------------------------------------------------- */

export const products = pgTable(
  'products',
  {
    id: uuid('id').primaryKey(),
    /** Stable id derived from the feed (not the DB surrogate key). */
    feedId: varchar('feed_id', { length: 255 }).notNull(),
    name: text('name').notNull(),
    marketplace: varchar('marketplace', { length: 64 }).notNull(),
    productUrl: text('product_url').notNull(),
    /**
     * Normalized form of `productUrl` used as the importer's dedupe key
     * (PART 3 `urlDuplicatesSkipped`), so PostgreSQL can reproduce the same
     * idempotency as the file catalog.
     */
    productUrlNormalized: text('product_url_normalized'),
    affiliateUrl: text('affiliate_url').notNull(),
    /** False when the feed supplied no affiliate link (plain product URL). */
    hasAffiliateLink: boolean('has_affiliate_link').notNull().default(false),
    price: doublePrecision('price'),
    currency: varchar('currency', { length: 16 }),
    commissionRate: doublePrecision('commission_rate'),
    imageUrl: text('image_url'),
    category: varchar('category', { length: 255 }),
    /** Stable slug id derived from the category display name (Part 3). */
    categoryId: varchar('category_id', { length: 64 }),
    description: text('description'),
    rating: doublePrecision('rating'),
    soldCount: integer('sold_count'),
    /** Catalog eligibility computed from imported fields only. */
    eligible: boolean('eligible').notNull().default(false),
    /** JSON array of machine-readable ineligibility reasons. */
    eligibilityReasons: text('eligibility_reasons').notNull().default('[]'),
    /** Unrecognized source columns, preserved verbatim as JSON. */
    extraColumns: text('extra_columns').notNull().default('{}'),
    lastImportedAt: timestamp('last_imported_at', { withTimezone: true }),
    /** Import batch identifier for traceability (FK added in migration 0002). */
    importBatchId: uuid('import_batch_id').references(() => importBatches.id, {
      onDelete: 'set null',
    }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // One row per feed product; re-imports upsert rather than duplicate.
    uniqueIndex('products_feed_id_marketplace_idx').on(t.feedId, t.marketplace),
    index('products_import_batch_idx').on(t.importBatchId),
    index('products_category_idx').on(t.categoryId),
    index('products_eligible_idx').on(t.eligible),
    index('products_url_normalized_idx').on(t.productUrlNormalized),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Slot content (Part 3: pipeline records)                                   */
/* -------------------------------------------------------------------------- */

/**
 * One row per content slot: the reserved product, the PERSISTED image count,
 * the selection policy snapshot and the pipeline stage. Uniqueness on
 * slot_key makes "two workers cannot reserve the same slot" a database
 * invariant (mirrored by the in-process lock in the file/memory store).
 */
export const slotContents = pgTable(
  'slot_contents',
  {
    id: uuid('id').primaryKey(),
    slotKey: varchar('slot_key', { length: 64 }).notNull(),
    stage: varchar('stage', { length: 32 }).notNull().default('reserved'),
    productId: uuid('product_id').references(() => products.id, { onDelete: 'set null' }),
    sourceProductId: varchar('source_product_id', { length: 255 }),
    productName: text('product_name'),
    affiliateUrl: text('affiliate_url'),
    categoryId: varchar('category_id', { length: 64 }),
    imageCountPolicy: varchar('image_count_policy', { length: 32 }).notNull().default('random_1_or_2'),
    /** Chosen ONCE per slot, persisted BEFORE generation. */
    imageCount: integer('image_count').notNull().default(1),
    imageCountChosenAt: timestamp('image_count_chosen_at', { withTimezone: true }),
    /** JSON snapshot of the selection policy + score signals. */
    selection: text('selection').notNull().default('{}'),
    referenceImageUrl: text('reference_url'),
    generationRunId: varchar('generation_run_id', { length: 64 }),
    /** JSON array of SlotAsset records (storage keys, checksums, prompts). */
    assets: text('assets').notNull().default('[]'),
    /** JSON array of SlotCaption records (per-platform text + validation). */
    captions: text('captions').notNull().default('[]'),
    validationPassed: boolean('validation_passed').notNull().default(false),
    /** JSON array of SlotBlocker records. */
    blockers: text('blockers').notNull().default('[]'),
    lastError: text('last_error'),
    attempts: integer('attempts').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
    completedAt: timestamp('completed_at', { withTimezone: true }),
    /**
     * Optimistic concurrency guard (PART 5): every committed write increments
     * it, and the UPDATE matches `WHERE version = <expected>` so a stale worker
     * that lost the lease updates 0 rows instead of overwriting newer results.
     */
    version: integer('version').notNull().default(1),
    /** Worker id that currently owns this slot's in-flight run, if any. */
    lockOwner: varchar('lock_owner', { length: 100 }),
    /** After this instant another worker may take over a crashed run's slot. */
    lockExpiresAt: timestamp('lock_expires_at', { withTimezone: true }),
  },
  (t) => [
    // The reservation uniqueness contract, enforced by the database.
    uniqueIndex('slot_contents_slot_key_idx').on(t.slotKey),
    index('slot_contents_stage_idx').on(t.stage),
    index('slot_contents_lock_idx').on(t.lockExpiresAt),
    index('slot_contents_completed_idx').on(t.completedAt),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Jobs (durable queue)                                                       */
/* -------------------------------------------------------------------------- */

export const jobs = pgTable(
  'jobs',
  {
    id: uuid('id').primaryKey(),
    kind: varchar('kind', { length: 100 }).notNull(),
    status: varchar('status', { length: 20 }).notNull().default('pending'),
    /** Uniqueness scope — prevents double-scheduling the same slot/product. */
    uniqueKey: varchar('unique_key', { length: 255 }).notNull(),
    scheduledFor: timestamp('scheduled_for', { withTimezone: true }).notNull(),
    attempts: integer('attempts').notNull().default(0),
    maxAttempts: integer('max_attempts').notNull().default(3),
    lastError: text('last_error'),
    payload: text('payload').notNull().default('{}'),
    claimedBy: varchar('claimed_by', { length: 100 }),
    /** When the current worker claimed the job (starts the lease window). */
    claimedAt: timestamp('claimed_at', { withTimezone: true }),
    /** After this instant the lease is expired and the job is recoverable. */
    leaseExpiresAt: timestamp('lease_expires_at', { withTimezone: true }),
    /**
     * Per-claim secret (PART 5): `complete`/`fail` must present it, so a worker
     * whose lease already expired cannot commit its result over a newer owner.
     */
    claimToken: uuid('claim_token'),
    completedAt: timestamp('completed_at', { withTimezone: true }),
    /** Structured outcome of the last attempt (JSON, never secrets). */
    result: text('result').notNull().default('{}'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // The core uniqueness contract, enforced by the database.
    uniqueIndex('jobs_unique_key_idx').on(t.uniqueKey),
    index('jobs_status_scheduled_idx').on(t.status, t.scheduledFor),
    index('jobs_lease_idx').on(t.status, t.leaseExpiresAt),
    index('jobs_kind_idx').on(t.kind),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Publish runs                                                               */
/* -------------------------------------------------------------------------- */

export const publishRuns = pgTable(
  'publish_runs',
  {
    id: uuid('id').primaryKey(),
    jobId: uuid('job_id').references(() => jobs.id, { onDelete: 'set null' }),
    productId: uuid('product_id').references(() => products.id, { onDelete: 'set null' }),
    /** Scheduler slot identity, e.g. "2026-10-12#03". */
    slotKey: varchar('slot_key', { length: 64 }).notNull(),
    provider: varchar('provider', { length: 32 }).notNull(),
    success: boolean('success').notNull().default(false),
    dryRun: boolean('dry_run').notNull().default(true),
    postId: varchar('post_id', { length: 255 }),
    permalink: text('permalink'),
    /** Redacted error detail when the run failed. */
    errorDetail: text('error_detail'),
    /** SHA-256 of the generated caption, for auditability without storing secrets. */
    captionHash: varchar('caption_hash', { length: 64 }),
    imageUrl: text('image_url'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // A provider is published at most once per slot (idempotency at the DB level).
    uniqueIndex('publish_runs_slot_provider_idx').on(t.slotKey, t.provider),
    index('publish_runs_job_idx').on(t.jobId),
  ],
);

/* -------------------------------------------------------------------------- */
/*  Notifications ledger                                                      */
/* -------------------------------------------------------------------------- */

export const notifications = pgTable(
  'notifications',
  {
    id: uuid('id').primaryKey(),
    /** Dedupe key — one delivery per key. */
    dedupeKey: varchar('dedupe_key', { length: 255 }).notNull(),
    kind: varchar('kind', { length: 40 }).notNull(),
    title: text('title').notNull(),
    delivered: boolean('delivered').notNull().default(false),
    transport: varchar('transport', { length: 20 }).notNull().default('mock'),
    telegramMessageId: varchar('telegram_message_id', { length: 64 }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex('notifications_dedupe_key_idx').on(t.dedupeKey)],
);

/* -------------------------------------------------------------------------- */
/*  Import batches                                                             */
/* -------------------------------------------------------------------------- */

export const importBatches = pgTable('import_batches', {
  id: uuid('id').primaryKey(),
  filename: varchar('filename', { length: 255 }).notNull(),
  format: varchar('format', { length: 8 }).notNull(),
  totalRows: integer('total_rows').notNull().default(0),
  accepted: integer('accepted').notNull().default(0),
  rejected: integer('rejected').notNull().default(0),
  duplicatesRemoved: integer('duplicates_removed').notNull().default(0),
  /** Rows the parser accepted that created a NEW catalog entry. */
  newProducts: integer('new_products').notNull().default(0),
  /** Rows that updated an existing catalog entry. */
  updatedProducts: integer('updated_products').notNull().default(0),
  /** Rows skipped because the normalized product URL already existed. */
  urlDuplicatesSkipped: integer('url_duplicates_skipped').notNull().default(0),
  categoriesSeen: integer('categories_seen').notNull().default(0),
  /** JSON array of per-row rejection reasons from the parser. */
  issues: text('issues').notNull().default('[]'),
  source: varchar('source', { length: 32 }).notNull().default('feed_import'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
});

/* -------------------------------------------------------------------------- */
/*  Application settings (Part 5: durable automation state)                   */
/* -------------------------------------------------------------------------- */

/**
 * The validated automation settings document (automationState, interval,
 * daily slot cap, selection mode, image-count policy, platform switches).
 *
 * Exactly one row exists — enforced by a CHECK constraint, not by convention —
 * so "load settings" can never observe two competing configurations.
 */
export const appSettings = pgTable(
  'app_settings',
  {
    id: smallint('id').primaryKey(),
    /** JSON-encoded `AutomationSettings` (re-validated on load). */
    doc: jsonb('doc').notNull(),
    /** Incremented on every write; used for optimistic updates. */
    version: integer('version').notNull().default(1),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (_t) => [check('app_settings_single_row', sql`id = 1`)],
);

/* -------------------------------------------------------------------------- */
/*  Scheduler checkpoints (Part 5: durable tick / anti-catch-up state)        */
/* -------------------------------------------------------------------------- */

/**
 * Durable scheduler state keyed by checkpoint name (`content_scheduler`).
 *
 * Persists what the scheduler last enqueued/executed/skipped so a restart can
 * report an honest last tick instead of pretending nothing ever ran. It does
 * NOT replace the slot/job uniqueness that actually prevents duplicate work.
 */
export const schedulerCheckpoints = pgTable('scheduler_checkpoints', {
  key: varchar('key', { length: 64 }).primaryKey(),
  /** JSON checkpoint document (slot keys, counts, stage summary). */
  doc: jsonb('doc').notNull().default(sql`'{}'::jsonb`),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});
